package glitch

import data.glitch_lib

credential_field_patterns := {"password", "passwd", "pwd", "secret", "secret_key", "access_key", "api_key", "token", "auth_token", "private_key", "certificate", "cert", "key", "secret_key", "root_password", "master_password", "bootstrap_password", "admin_password", "initial_password", "setup_password", "connection_string", "dsn", "uri", "database_url", "ssh_public_key", "ssh_private_key", "key_data", "key_content", "ca_cert", "public_key", "public_key_openssh", "public_key_pem", "private_key_pem", "ciphertext", "plaintext", "sensitive_content", "webhook_secret", "client_secret", "oauth_client_secret", "vault_token"}

insecure_default_values := {"admin", "root", "default", "guest", "test", "user", "system", "anonymous", "password", "pass", "secret", "123456", "changeme", "admin123", "root123", "test123", "password123", "secret123"}

has_credential_field_name(name) {
    lower_name := lower(name)
    pattern := credential_field_patterns[_]
    contains(lower_name, pattern)
}

looks_like_hardcoded_credential(value) {
    value.ir_type == "String"
    str := value.value
    count(str) > 0
    not starts_with(str, "var.")
    not starts_with(str, "local.")
    not starts_with(str, "module.")
    not starts_with(str, "data.")
    not starts_with(str, "${")
    not is_external_reference(value)
    looks_like_secret_value(str)
}

looks_like_secret_value(str) {
    default_val := insecure_default_values[_]
    lower(str) == default_val
} else {
    regex.match(`^[A-Za-z0-9+/]{20,}={0,2}$`, str)
    count(str) >= 24
} else {
    regex.match(`^[0-9a-f]{32,}$`, str)
} else {
    regex.match(`^[0-9A-F]{32,}$`, str)
} else {
    regex.match(`^-----BEGIN (RSA |DSA |EC |OPENSSH )?PRIVATE KEY-----`, str)
} else {
    regex.match(`://[^:]+:[^@]+@`, str)
} else {
    regex.match(`^[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}`, str)
}

is_external_reference(value) {
    walk(value, [_, n])
    n.ir_type == "VariableReference"
} else {
    walk(value, [_, n])
    n.ir_type == "FunctionCall"
    reference_function(n.name)
}

reference_function(name) {
    reference_funcs := {"file", "templatefile", "data", "var", "local", "module", "vault", "aws_secretsmanager", "azurerm_key_vault_secret", "google_secret_manager"}
    func := reference_funcs[_]
    contains(lower(name), func)
}

has_sensitive_pair(attrs) {
    attr_names := {lower(a.name) | a := attrs[_]}
    count({x | x := attr_names[_]; contains(x, "user") or contains(x, "username") or x == "user"}) > 0
    count({x | x := attr_names[_]; contains(x, "pass") or contains(x, "password") or contains(x, "secret") or contains(x, "key")}) > 0
}

is_credential_block(node) {
    lower_type := lower(node.type)
    credential_blocks := {"auth", "authentication", "credentials", "login", "user_data", "identity", "basic_auth", "http_auth", "api_auth", "oauth", "iam_user", "service_account"}
    block := credential_blocks[_]
    contains(lower_type, block)
